package dev.bennett.codexmeter;

import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;

/** Detached emulator fixture; real Activities/SQLite, never a production phone package. */
public final class PhaseANativeTest extends Instrumentation {
    int checks;Context c;Throwable error;
    void check(boolean b,String reason){checks++;if(!b)throw new AssertionError(reason);}
    void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable t){error=t;}});if(error!=null)throw new AssertionError(error);waitForIdleSync();}
    TextView text(View v,String label){if(v.getVisibility()!=View.VISIBLE)return null;if(v instanceof TextView&&label.contentEquals(((TextView)v).getText()))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView found=text(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
    void ready(Activity a)throws Exception {for(int i=0;i<120;i++){Thread.sleep(60);boolean[] done={false};main(()->done[0]=text(a.getWindow().getDecorView(),a.getString(R.string.next_loading))==null);if(done[0])return;}throw new AssertionError("Activity loading timeout");}
    void invoke(Object target,String method)throws Exception{Method m=target.getClass().getSuperclass()==LedgerAnalyticsActivity.class?LedgerAnalyticsActivity.class.getDeclaredMethod(method):target.getClass().getDeclaredMethod(method);m.setAccessible(true);m.invoke(target);}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){Bundle result=new Bundle();try {
        c=getTargetContext();check(c.getPackageName().endsWith(".rpg3qa"),"Isolated package required");
        AppPreferences.setAutomaticRefresh(c,false);AppPreferences.setRefreshOnLaunch(c,false);UpdatePreferences.setAutomaticChecks(c,false);AppPreferences.setAppTheme(c,"dark");AppPreferences.completeOnboarding(c);AppPreferences.setShowUsageOverview(c,true);AppPreferences.setShowDashboardWeekly(c,true);((android.app.job.JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).cancelAll();RefreshScheduler.cancelAll(c);ResetAlertScheduler.cancelAll(c);ResetCreditExpiryScheduler.cancelAll(c);
        long now=System.currentTimeMillis();SecureTokenStore.save(c,new AuthTokens("PHASE_A_QA_FAKE","PHASE_A_QA_FAKE_REFRESH","",now+86400000L,"phase-a-synthetic-"+UUID.randomUUID(),""));TaskStatusStore.enable(c,false);
        UsageWindow w=new UsageWindow(48.12345,604800,0,(now+86400000L)/1000);
        UsageSnapshot snapshot=new UsageSnapshot("pro",true,false,null,w,now);AppPreferences.saveSnapshot(c,snapshot);
        long floor=UsageLedgerDatabase.lanFloor(c);UsageLedgerDatabase.mergeLan(c,List.of(new LedgerRecord("weekly","pro",now-3600000,45.223,"45.223",w.resetAtMillis(),604800,"api_precise",false),new LedgerRecord("weekly","pro",now,48.12345,"48.12345",w.resetAtMillis(),604800,"api_precise",false)),floor);
        String key=SubscriptionStore.key(c,snapshot);java.time.LocalDate today=LedgerAggregation.day(now);SubscriptionCost cost=new SubscriptionCost("100","USD",today.minusDays(3),today.plusDays(27));check(SubscriptionStore.save(c,snapshot,key,cost),"QA payment saved");RpgProgressStore.reconcile(c,snapshot,UsageLedgerDatabase.load(c));
        AppPreferences.clearLastError(c);Map<String,?> preserved=new HashMap<>(c.getSharedPreferences("codex_meter_settings_v1",0).getAll());
        MainActivity home=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready(home);
        for(int width:new int[]{320,360,411})for(float font:new float[]{1f,1.5f})for(Locale locale:new Locale[]{Locale.KOREAN,Locale.ENGLISH}){
            main(()->{AppPreferences.saveSnapshot(c,new UsageSnapshot("pro",true,false,null,w,System.currentTimeMillis()));Configuration conf=new Configuration(home.getResources().getConfiguration());conf.screenWidthDp=width;conf.fontScale=font;conf.setLocale(locale);home.getResources().updateConfiguration(conf,home.getResources().getDisplayMetrics());try{Field stamp=MainActivity.class.getDeclaredField("renderedSignature");stamp.setAccessible(true);stamp.set(home,"");invoke(home,"rebuild");}catch(Exception e){throw new RuntimeException(e);}});ready(home);
            main(()->{shot("home-diagnostic",home.findViewById(R.id.dashboard_scroll),width,1000);check(text(home.getWindow().getDecorView(),home.getString(R.string.phase_a_confirmed))!=null,"Actual home marks confirmed source at "+width+"/"+font+"/"+locale.getLanguage()+": "+AppPreferences.getLastError(c));shot("home-"+width+"-"+font+"-"+locale.getLanguage(),home.findViewById(R.id.dashboard_scroll),width,1000);});
        }
        AppPreferences.setLastError(c,"Synthetic offline");main(()->{try{invoke(home,"rebuild");}catch(Exception e){throw new RuntimeException(e);}});ready(home);main(()->{check(text(home.getWindow().getDecorView(),home.getString(R.string.phase_a_cached_failed))!=null,"Fresh cache after failure is labeled failed");shot("home-offline",home.findViewById(R.id.dashboard_scroll),360,1000);});
        AppPreferences.clearLastError(c);main(()->home.finish());
        Map<String,?> afterHome=new HashMap<>(c.getSharedPreferences("codex_meter_settings_v1",0).getAll());preserved.remove("last_snapshot");afterHome.remove("last_snapshot");check(preserved.equals(afterHome),"Home preserves settings apart from explicitly refreshed QA snapshot: "+preserved.keySet()+" / "+afterHome.keySet());preserved=new HashMap<>(c.getSharedPreferences("codex_meter_settings_v1",0).getAll());
        RecordsActivity records=(RecordsActivity)startActivitySync(new Intent(c,RecordsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready(records);
        for(int width:new int[]{320,360,411})for(float font:new float[]{1f,1.5f})for(Locale locale:new Locale[]{Locale.KOREAN,Locale.ENGLISH}) {
            main(()->{Configuration conf=new Configuration(records.getResources().getConfiguration());conf.screenWidthDp=width;conf.fontScale=font;conf.setLocale(locale);records.getResources().updateConfiguration(conf,records.getResources().getDisplayMetrics());try{invoke(records,"controls");}catch(Exception e){throw new RuntimeException(e);}});
            main(()->{shot("records-"+width+"-"+font+"-"+locale.getLanguage(),records.findViewById(R.id.dashboard_scroll),width,1200);check(text(records.getWindow().getDecorView(),records.getString(R.string.v3_observations))!=null,"Calendar has date details action");check(text(records.getWindow().getDecorView(),records.getString(R.string.v3_this_window))==null,"Calendar does not duplicate trend selectors");TextView trends=text(records.getWindow().getDecorView(),records.getString(R.string.ui_ledger_trends));check(trends!=null,"Trend entry exists");trends.performClick();});
            main(()->{shot("trends-"+width+"-"+font+"-"+locale.getLanguage(),records.findViewById(R.id.dashboard_scroll),width,1200);check(text(records.getWindow().getDecorView(),records.getString(R.string.v3_this_window))!=null,"Trend periods functional");check(text(records.getWindow().getDecorView(),records.getString(R.string.v3_observations))==null,"Trend omits duplicate calendar detail");TextView calendar=text(records.getWindow().getDecorView(),records.getString(R.string.next_calendar));calendar.performClick();});
        }
        main(()->{AlertDialog help=OptionalSetupUi.show(records,true);shot("optional-help",help.getWindow().getDecorView(),360,1050);for(String id:new String[]{"pc","widgets","achievements","titles","payment","notifications"})check(help.getWindow().getDecorView().findViewWithTag("optional:"+id)!=null,"Optional entry "+id);help.dismiss();});
        check(preserved.equals(c.getSharedPreferences("codex_meter_settings_v1",0).getAll()),"Viewing help and records does not change user settings");check(AppPreferences.isOnboardingComplete(c),"Completion retained");
        UsageLedgerDatabase.Data before=UsageLedgerDatabase.load(c);main(()->records.finish());RecordsActivity reopened=(RecordsActivity)startActivitySync(new Intent(c,RecordsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready(reopened);check(UsageLedgerDatabase.load(c).records.size()==before.records.size(),"SQLite records survive reopen");main(()->reopened.finish());
        result.putString("stream","Phase A native: "+checks+" checks passed; real activity paths / synthetic emulator account.\n");finish(-1,result);
    }catch(Throwable t){StringWriter writer=new StringWriter();t.printStackTrace(new PrintWriter(writer));result.putString("stream",writer.toString());finish(0,result);}}
    void shot(String name,View v,int width,int height){try{int w=Ui.dp(c,width),h=Ui.dp(c,height);v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.AT_MOST));v.layout(0,0,w,v.getMeasuredHeight());Bitmap b=Bitmap.createBitmap(w,Math.max(1,v.getMeasuredHeight()),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(0xff0d0e10);v.draw(canvas);File folder=new File(c.getExternalFilesDir(null),"phase-a-fixtures");folder.mkdirs();try(FileOutputStream output=new FileOutputStream(new File(folder,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,output);}b.recycle();}catch(Exception e){throw new RuntimeException(e);}}
}
